WITH recent_orders AS (SELECT *, DATEDIFF(CURRENT_DATE(), order_date) / 7 AS weeks_since_order_date FROM orders WHERE order_date >= '2025-09-01'), Agg AS (SELECT channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, ROUND(AVG(shipping_fee), 2) AS avg_shipping_fee FROM recent_orders GROUP BY channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM Agg WHERE avg_shipping_fee < 60 ORDER BY avg_shipping_fee DESC, channel, order_cohort LIMIT 5
